(7550916, 1209560, 123833, '<td valign="top">Nice composition</td>', 'Nice composition', '2018-01-03 03:33:27.000000', NULL, 1),
(7550923, 1209588, 114285, '<td valign="top">Great scene, but lacks structure and sharpness such a great shame, with a little bit of professional editing this could''ve shined.</td>', 'Great scene, but lacks structure and sharpness such a great shame, with a little bit of professional editing this could''ve shined.', '2018-01-03 04:43:00.000000', NULL, 1),
(7550924, 1209612, 114285, '<td valign="top">Pretty scene, but the blue highlights really spoil this, with a little bit of editing you could''ve toned this down.</td>', 'Pretty scene, but the blue highlights really spoil this, with a little bit of editing you could''ve toned this down.', '2018-01-03 04:44:13.000000', NULL, 1),
(7550925, 1209487, 114285, '<td valign="top">A landscape with some unattractive homes in front, a sign and some overhead wires never make for a dramatic scene. Remove the clutter and you''ll get a great photo.</td>', 'A landscape with some unattractive homes in front, a sign and some overhead wires never make for a dramatic scene. Remove the clutter and you''ll get a great photo.', '2018-01-03 04:45:25.000000', NULL, 1),
(7550926, 1209556, 114285, '<td valign="top">Spectacular lighting here, what a scene!</td>', 'Spectacular lighting here, what a scene!', '2018-01-03 04:47:14.000000', NULL, 1),
(7550932, 1209512, 100393, '<td valign="top">Gorgeous shot - a shame it isn''t presented at the maximum allowable size.</td>', 'Gorgeous shot - a shame it isn''t presented at the maximum allowable size.', '2018-01-03 07:30:17.000000', NULL, 1),
(7550938, 1209687, 12611, '<td valign="top">Almost a Wyeth feel to it- I can feel the ominous mood swings of winter.</td>', 'Almost a Wyeth feel to it- I can feel the ominous mood swings of winter.', '2018-01-03 09:59:25.000000', NULL, 1),
(7550939, 1209934, 12611, '<td valign="top">The composition is terrific- the slant gives movement- the light is a bit bright, if this shot was golden hour it would be a classic for the ages...</td>', 'The composition is terrific- the slant gives movement- the light is a bit bright, if this shot was golden hour it would be a classic for the ages...', '2018-01-03 10:00:34.000000', NULL, 1),
(7550951, 1209651, 181814, '<td valign="top">Very nice photograph overall. I like the composition, and the exposure is excellent. Your focus is excellent throughout, exciting scene I must say.</td>', 'Very nice photograph overall. I like the composition, and the exposure is excellent. Your focus is excellent throughout, exciting scene I must say.', '2018-01-03 14:22:08.000000', NULL, 1),
(7550952, 1209889, 181814, '<td valign="top">Great looking photograph, black and white does it justice. I am a big fan of old houses and cabins, so this is right up my alley. Very well done, you should be proud of this one.</td>', 'Great looking photograph, black and white does it justice. I am a big fan of old houses and cabins, so this is right up my alley. Very well done, you should be proud of this one.', '2018-01-03 14:26:22.000000', NULL, 1),
(7550953, 1209934, 181814, '<td valign="top">Postcard quality photograph for sure. I like everything about this photo; it seems to tell a story about the location. You obtained excellent focus, composition, and exposure.  One of my favorites in this contest.</td>', 'Postcard quality photograph for sure. I like everything about this photo; it seems to tell a story about the location. You obtained excellent focus, composition, and exposure.  One of my favorites in this contest.', '2018-01-03 14:30:54.000000', NULL, 1),
(7550954, 1209428, 181814, '<td valign="top">I like the point of view and the leading lines throughout your photograph. Exposure, composition, and focus are the best. I will give this entry a high score.</td>', 'I like the point of view and the leading lines throughout your photograph. Exposure, composition, and focus are the best. I will give this entry a high score.', '2018-01-03 14:33:19.000000', NULL, 1),
(7550955, 1209645, 181814, '<td valign="top">Great idea of the small child walking on the snow-covered trail it does enhance this photograph significantly. Composition, exposure and white balance are spot on,</td>', 'Great idea of the small child walking on the snow-covered trail it does enhance this photograph significantly. Composition, exposure and white balance are spot on,', '2018-01-03 14:36:23.000000', NULL, 1),
(7550957, 1209936, 181814, '<td valign="top">Calendar material for sure. Excellent composition, focus, exposure and white balance. The horse makes this a fantastic photograph, and the surrounding area stands out.</td>', 'Calendar material for sure. Excellent composition, focus, exposure and white balance. The horse makes this a fantastic photograph, and the surrounding area stands out.', '2018-01-03 14:38:57.000000', NULL, 1),
(7550959, 1209890, 181814, '<td valign="top">Probably a cityscape rather than a winter landscape, nothing the less, it''s a great photograph. Composition, focus, and exposure are excellent. Black and white looks great in this scenario.</td>', 'Probably a cityscape rather than a winter landscape, nothing the less, it''s a great photograph. Composition, focus, and exposure are excellent. Black and white looks great in this scenario.', '2018-01-03 14:42:02.000000', NULL, 1),
(7550960, 1209924, 181814, '<td valign="top">You have a great eye; the frozen river makes the dead grass and the over-all scene stand out. Exposure, composition focus and leading lines make this terrific to view.</td>', 'You have a great eye; the frozen river makes the dead grass and the over-all scene stand out. Exposure, composition focus and leading lines make this terrific to view.', '2018-01-03 14:44:55.000000', NULL, 1),
(7550961, 1209520, 181814, '<td valign="top">You could have cleaned up some of the dust spots in the sky and straightened the horizon to make this into a lovely winter landscape. The underexposure throughout is very distracting.</td>', 'You could have cleaned up some of the dust spots in the sky and straightened the horizon to make this into a lovely winter landscape. The underexposure throughout is very distracting.', '2018-01-03 14:49:14.000000', NULL, 1),
(7550962, 1209960, 181814, '<td valign="top">I would like to see a bit more contrast, but the high ket look would make a great month for a calendar. I will give this a high score because I can see it is well composed and I sort of like the pastel colors and as I said it has a place on a calendar.</td>', 'I would like to see a bit more contrast, but the high ket look would make a great month for a calendar. I will give this a high score because I can see it is well composed and I sort of like the pastel colors and as I said it has a place on a calendar.', '2018-01-03 14:52:45.000000', NULL, 1),
(7550963, 1209913, 181814, '<td valign="top">Simplicity is the reason this photograph is among my favorites. Composition, exposure and white balance are fantastic. Perfect ten from me, a worthy winner.</td>', 'Simplicity is the reason this photograph is among my favorites. Composition, exposure and white balance are fantastic. Perfect ten from me, a worthy winner.', '2018-01-03 14:55:56.000000', NULL, 1),
(7550964, 1209687, 181814, '<td valign="top">Fantastic find and capture. The trail leading to the cabin on the hill is exceptionally well composed. Exposure, focus and white balance are excellent.</td>', 'Fantastic find and capture. The trail leading to the cabin on the hill is exceptionally well composed. Exposure, focus and white balance are excellent.', '2018-01-03 14:58:33.000000', NULL, 1),
(7550965, 1209460, 181814, '<td valign="top">Perfect time of the day for this photograph. Composition, focus, exposure and white balance are excellent. I like the picture from foreground to the background and everything in between.</td>', 'Perfect time of the day for this photograph. Composition, focus, exposure and white balance are excellent. I like the picture from foreground to the background and everything in between.', '2018-01-03 15:02:36.000000', NULL, 1),
(7550973, 1209934, 3306, '<td valign="top">I really like this scene. I feel as if it would be even better if you cropped it tighter on the left to remove the dead space. This would make the barn and the beautiful dog more the subject of the composition and give it greater appeal. Thanks for posting.</td>', 'I really like this scene. I feel as if it would be even better if you cropped it tighter on the left to remove the dead space. This would make the barn and the beautiful dog more the subject of the composition and give it greater appeal. Thanks for posting.', '2018-01-03 18:09:22.000000', NULL, 1),
(7550974, 1209687, 3306, '<td valign="top">Nice composition. Excellent leading line to the barn.</td>', 'Nice composition. Excellent leading line to the barn.', '2018-01-03 18:12:26.000000', NULL, 1),
(7550975, 1209683, 3306, '<td valign="top">The person makes the picture! Gives it wonderful perspective.</td>', 'The person makes the picture! Gives it wonderful perspective.', '2018-01-03 18:20:29.000000', NULL, 1),
