(7551128, 1209830, 65234, '<td valign="top">Pretty scene and I love that sky. I know it''s a low light scene, but I still think I would brighten at least the foreground, maybe all the way up to the clouds.</td>', 'Pretty scene and I love that sky. I know it''s a low light scene, but I still think I would brighten at least the foreground, maybe all the way up to the clouds.', '2018-01-05 08:27:38.000000', NULL, 1),
(7551129, 1209556, 65234, '<td valign="top">Quite a scene to be watching. The people give it a nice sense of scale.</td>', 'Quite a scene to be watching. The people give it a nice sense of scale.', '2018-01-05 08:28:41.000000', NULL, 1),
(7551130, 1209460, 65234, '<td valign="top">I like the rays of the sun about to brighten the cold, blue landscape. Detail on the foreground snow is nice; I''d back it off a little on the rocks as they look over HDRed to me.</td>', 'I like the rays of the sun about to brighten the cold, blue landscape. Detail on the foreground snow is nice; I''d back it off a little on the rocks as they look over HDRed to me.', '2018-01-05 08:30:36.000000', NULL, 1),
(7551131, 1209945, 65234, '<td valign="top">Love the leading line. I kind of want to clone out the building on the left to make the primary one more even more isolated.</td>', 'Love the leading line. I kind of want to clone out the building on the left to make the primary one more even more isolated.', '2018-01-05 08:32:03.000000', NULL, 1),
(7551132, 1209943, 65234, '<td valign="top">White as far as the eye can see, but without losing the details of the scene.</td>', 'White as far as the eye can see, but without losing the details of the scene.', '2018-01-05 08:32:46.000000', NULL, 1),
(7551133, 1209937, 65234, '<td valign="top">I feel like the trees are moving! Nice light and I rather like the blur.</td>', 'I feel like the trees are moving! Nice light and I rather like the blur.', '2018-01-05 08:33:29.000000', NULL, 1),
(7551134, 1209687, 65234, '<td valign="top">Nice, curvy leading line. Looks very isolated up there.</td>', 'Nice, curvy leading line. Looks very isolated up there.', '2018-01-05 08:34:07.000000', NULL, 1),
(7551135, 1209426, 65234, '<td valign="top">Cold and lonely. IMO the benches take up too much of the image for a landscape.</td>', 'Cold and lonely. IMO the benches take up too much of the image for a landscape.', '2018-01-05 08:35:40.000000', NULL, 1),
(7551136, 1209926, 65234, '<td valign="top">I really like this image, with its industrial structures looming over the natural foreground. But ... it doesn''t feel like any particular season to me. I know I''m responding to this with my own interpretation of winter and that may be quite unreasonable. B&amp;W or a blue duotone would work better for my prejudices, FWIW.</td>', 'I really like this image, with its industrial structures looming over the natural foreground. But ... it doesn''t feel like any particular season to me. I know I''m responding to this with my own interpretation of winter and that may be quite unreasonable. B&W or a blue duotone would work better for my prejudices, FWIW.', '2018-01-05 08:40:19.000000', NULL, 1),
(7551137, 1209512, 42733, '<td valign="top">My favorite in this challenge.</td>', 'My favorite in this challenge.', '2018-01-05 09:14:46.000000', NULL, 1),
