(7552052, 1209595, 33068, '<td valign="top">Fantastic composition.</td>', 'Fantastic composition.', '2018-01-10 18:35:54.000000', NULL, 0),
(7552063, 1209934, 35804, '<td valign="top">This is so lovely Mary Ann. I was one of the 9s. I don''t get those low votes either. I think it''s an image that benefits from being viewed as large as possible so one can drink all the detail in...the colors, textures, the moment. It reminds me of a Wyeth painting, and I think that''s why I enjoy this so much.</td>', 'This is so lovely Mary Ann. I was one of the 9s. I don''t get those low votes either. I think it''s an image that benefits from being viewed as large as possible so one can drink all the detail in...the colors, textures, the moment. It reminds me of a Wyeth painting, and I think that''s why I enjoy this so much.', '2018-01-10 19:36:34.000000', NULL, 0),
(7552064, 1209659, 35804, '<td valign="top">No comments?! I was your 9. I loved the subtle color gradations and all the boats in a neat little row. Very nice.</td>', 'No comments?! I was your 9. I loved the subtle color gradations and all the boats in a neat little row. Very nice.', '2018-01-10 19:39:37.000000', NULL, 0),
